:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-mist-surface: #f9f9fb;
  --color-indigo-ink: #1f1f47;
  --color-slate-body: #3d3d5c;
  --color-pewter-caption: #6c7693;
  --color-quartz-border: #eaedf6;
  --color-lavender-ring: #8998e6;
  --color-periwinkle-signal: #576ddb;
  --color-cobalt-link: #3d52b8;
  --color-ember-coral: #f2545c;
  --color-frosted-lilac: #c1c9f6;
  --color-frosted-rose: #f7d4d4;
  --color-frosted-mint: #c1f6e0;

  /* Typography — Font Families */
  --font-object-sans: "Object Sans", "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-helvetica-neue: "Helvetica Neue", Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.25;
  --tracking-small: -0.12px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body-sm: 16px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 18px;
  --leading-body: 1.56;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.375;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.375;
  --tracking-subheading: -0.48px;
  --text-heading-sm: 28px;
  --leading-heading-sm: 1.0;
  --tracking-heading-sm: -1.12px;
  --text-heading: 32px;
  --leading-heading: 1.125;
  --tracking-heading: -0.64px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1.125;
  --tracking-heading-lg: -2.24px;
  --text-display: 60px;
  --leading-display: 1.125;
  --tracking-display: -2.4px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-120: 120px;

  /* Layout */
  --layout-page-max-width: 1280px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 32px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 16px;
  --radius-xl: 32px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 16px;
  --radius-images: 16px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-inputs: 9999px;
  --radius-tags: 9999px;
  --radius-small-cards: 32px;
  --radius-nav: 4px;
  --radius-small-elements: 2px;

  /* Shadows */
  --shadow-subtle: 0px 3px 16px 0px rgba(73, 46, 107, 0.14);
  --shadow-sm: 0px 6px 16px 0px rgba(61, 75, 143, 0.15);
  --shadow-md: 0px 6px 20px 0px rgba(230, 233, 248, 0.7), 0px 2px 8px 0px rgba(92, 112, 214, 0.2);
  --shadow-md-2: 0px 6px 20px 0px rgba(248, 230, 230, 0.6), 0px 2px 8px 0px rgba(191, 64, 64, 0.12);
  --shadow-md-3: 0px 6px 20px 0px rgba(219, 240, 231, 0.6), 0px 2px 8px 0px rgba(76, 178, 136, 0.16);
  --shadow-lg: 5px 5px 20px 0px rgba(71, 92, 133, 0.1), 0px 30px 60px 0px rgba(144, 138, 208, 0.1);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-surface: #f9f9fb;
  --surface-frosted-lilac: #c1c9f6;
  --surface-slate-body: #3d3d5c;
}

